  getDepartmentInfo(deptId) {
    const lang = this.currentLang || 'en';
    const dept = this.deptMap[deptId];
    if (dept) {
      const info = dept[lang] || dept.en;
      if (info) return info;
    }
    return null;
  },

  t(key) {
    const langObj = TRANSLATIONS[this.currentLang] || TRANSLATIONS.en;
    return langObj[key] || TRANSLATIONS.en[key] || key;
  },

  applyTranslations() {
    this.setLanguage(this.currentLang || 'en');
  },

  setLanguage(lang) {
    if (!TRANSLATIONS[lang]) lang = 'en';
    this.currentLang = lang;
    document.documentElement.lang = lang;

    // Update all elements with data-i18n
    document.querySelectorAll('[data-i18n]').forEach((el) => {
      const key = el.getAttribute('data-i18n');
      const val = this.t(key);
      if (!val) return;
      if (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA') {
        el.placeholder = val;
      } else if (el.tagName === 'OPTION') {
        el.textContent = val;
      } else {
        const hasSvg = el.querySelector('svg');
        const innerSpan = el.querySelector(':scope > span:not(.btn-icon-svg)');
        if (hasSvg) {
          if (innerSpan) {
            innerSpan.textContent = val;
          } else {
            const textNode = Array.from(el.childNodes).find(n => n.nodeType === 3 && n.nodeValue.trim().length > 0);
            if (textNode) {
              textNode.nodeValue = ' ' + val;
            } else {
              el.appendChild(document.createTextNode(' ' + val));
            }
          }
        } else {
          el.textContent = val;
        }
      }
    });

    // Update all placeholders with data-i18n-ph
    document.querySelectorAll('[data-i18n-ph]').forEach((el) => {
      const key = el.getAttribute('data-i18n-ph');
      const val = this.t(key);
      if (val) el.placeholder = val;
    });

    // Update current active language badge in header
    const langBadge = document.getElementById('current-lang-pill');
    if (langBadge) {
      langBadge.innerText = lang.toUpperCase();
    }
  },

